package com.andye.warmod.radar.station.client;import com.andye.warmod.radar.station.network.*;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.resources.Identifier;public final class ClientRadarStationState {public static final ClientRadarStationState INSTANCE=new ClientRadarStationState();private final Map<UUID,ClientRadarBlip>blips=new LinkedHashMap<>();private UUID radarId;private BlockPos centre;private Identifier dimension;private long serverGameTime,phaseOffset;private int sweepPeriod;private double detectionRange,warningRadius;private boolean warningActive;private int contacts,threats;private ClientRadarStationState(){}public void open(ClientboundOpenRadarStationPayload p){clear();radarId=p.radarId();centre=p.centre();dimension=p.dimension();serverGameTime=p.serverGameTime();sweepPeriod=p.sweepPeriodTicks();detectionRange=p.detectionRange();warningRadius=p.warningRadius();phaseOffset=p.phaseOffset();}public void observe(ClientboundRadarStationObservationPayload p){if(!p.radarId().equals(radarId))return;for(var o:p.observations())blips.put(o.trackId(),new ClientRadarBlip(o,o.observationGameTime()));contacts=blips.size();}public void state(ClientboundRadarStationStatePayload p){if(!p.radarId().equals(radarId))return;warningRadius=p.warningRadius();warningActive=p.warningActive();contacts=p.contacts();threats=p.threats();serverGameTime=p.serverGameTime();}public void prune(double now){blips.values().removeIf(b->b.alpha(now,sweepPeriod)<=0);}public Collection<ClientRadarBlip>blips(){return List.copyOf(blips.values());}public UUID radarId(){return radarId;}public BlockPos centre(){return centre;}public Identifier dimension(){return dimension;}public int sweepPeriod(){return sweepPeriod;}public double detectionRange(){return detectionRange;}public double warningRadius(){return warningRadius;}public long phaseOffset(){return phaseOffset;}public boolean warningActive(){return warningActive;}public int contacts(){return contacts;}public int threats(){return threats;}public boolean open(){return radarId!=null;}public void clear(){blips.clear();radarId=null;centre=null;dimension=null;serverGameTime=0;phaseOffset=0;sweepPeriod=80;detectionRange=8192;warningRadius=256;warningActive=false;contacts=threats=0;}}